      message: NativeInputArena.copyUTF8Slice(
        data: raw.messages,
        size: raw.messages_size,
        offset: item.message_offset,
        length: item.message_size
      )
    ) }
  }

  func nativeValue(arena _: NativeInputArena) throws
    -> mln_runtime_event_batch_view
